NEW_FILES = {'site_night_drop.py': '"""\nsite_night_drop.py  --  a bank\'s night depository beside its door\n==================================================================\nThe walker\'s bank list, outside (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md, researched): "a night depository\nis a slot in the wall for after-hours deposits: envelopes for people, locking zip bags for businesses, collected the\nnext morning". Zoo 1.138.0 draws it (`night_drop`); this hangs it.\n\nWHERE. On the facade the bank\'s door sign is on (`lot.bank_fronts`: the storefront Deli Counter chose for its sign),\nbeside the door nearest the sign: `site_posters.OPENING_KEEP` clear of that door and of every other storey-0 opening\non the wall (a storefront\'s windows), `site_posters.CORNER_KEEP` from the corners. The door\'s two sides are tried\nfirst, then the free span nearest the door that holds the plate. A facade with no such span gets none, and says so.\n\nHOW. A HUNG piece, as a poster run on an alley wall is (`site_posters`): its own list, never cover, a slot all the\nsame so the kit that builds the street builds it, with no collision -- a 0.15 m plate on a wall is not a thing a body\nstands behind. Its back `site_posters.AIR` off the wall\'s face, turned so its front (Zoo\'s local -Y) faces out\n(`site_posters.facing_yaw`), its centre `CENTRE_Z` up so the chute sits about a metre off the ground.\n\nFrame: spec/Blender Z-up plan coordinates, metres. Pure.\n"""\nfrom __future__ import annotations\n\nSPECIES = "night_drop"\n#: Zoo\'s genome default (1.138.0): the plate\'s width, its depth off the wall, its height.\nDIMS = (0.6, 0.15, 0.9)\n#: The plate\'s centre over the ground: its chute (the hood\'s centre, 0.08 of the height below the middle) at about a\n#: metre, a car window\'s height for a business\'s bag and an arm\'s for an envelope.\nCENTRE_Z = 1.1\nCODE = "LOT_NIGHT_DROP"\n\n\ndef _side_of(rect, point):\n    x0, y0, x1, y1 = rect\n    d = {"S": abs(point[1] - y0), "N": abs(point[1] - y1), "W": abs(point[0] - x0), "E": abs(point[0] - x1)}\n    return min(d, key=d.get)\n\n\ndef plan(site_spec, merged, banks, rects, findings=None):\n    """The night drops, one a bank at most, as hung records. ``banks`` is `lot.bank_fronts`\' ``[(id, (x, y) of its\n    door sign, business)]``, ``rects`` {building id: world plan rect}."""\n    import site_posters as SP\n    bdefs = {b["id"]: b for b in site_spec.get("buildings") or [] if "id" in b}\n    w, d, _h = DIMS\n    out = []\n    for bid, sign, _business in banks:\n        rect, bdef = rects.get(bid), bdefs.get(bid)\n        if rect is None or bdef is None:\n            continue\n        side = _side_of(rect, sign)\n        _s, nx, ny, line, lo, hi = next(s for s in SP._sides(rect) if s[0] == side)\n        ops = SP._openings_on(merged, bdef, rect, side)\n        u_sign = sign[0] if side in ("S", "N") else sign[1]\n        if not ops:\n            _say(findings, f"{CODE}_NO_DOOR: {bid}\'s {side} facade carries no storey-0 opening to stand one beside")\n            continue\n        door_u, door_hw = min(ops, key=lambda o: abs(o[0] - u_sign))\n        holes = [(u - hw - SP.OPENING_KEEP, u + hw + SP.OPENING_KEEP) for u, hw in ops]\n        spans = SP._free(lo + SP.CORNER_KEEP, hi - SP.CORNER_KEEP, holes)\n        fits = [(s, e) for s, e in spans if e - s >= w - 1e-9]\n        beside = [door_u + k * (door_hw + SP.OPENING_KEEP + w / 2.0) for k in (1, -1)]\n        u = next((c for c in beside if any(s <= c - w / 2.0 + 1e-9 and c + w / 2.0 <= e + 1e-9 for s, e in fits)), None)\n        if u is None and fits:\n            # the free span nearest the door, the plate at its end nearest the door\n            s, e = min(fits, key=lambda f: min(abs(f[0] - door_u), abs(f[1] - door_u)))\n            u = s + w / 2.0 if abs(s - door_u) <= abs(e - door_u) else e - w / 2.0\n        if u is None:\n            _say(findings, f"{CODE}_NO_ROOM: {bid}\'s {side} facade has no {w:.2f} m between its openings")\n            continue\n        off = d / 2.0 + SP.AIR\n        at = (u + nx * off, line + ny * off) if side in ("S", "N") else (line + nx * off, u + ny * off)\n        out.append({"name": f"NightDrop_{bid}", "species": SPECIES, "at": [round(at[0], 4), round(at[1], 4)],\n                    "yaw": SP.facing_yaw(nx, ny), "dims": list(DIMS), "z": CENTRE_Z, "base": None,\n                    "host": f"wall:{bid}:{side}", "source": "site_night_drop"})\n        _say(findings, f"{CODE}: {bid} on its {side} facade at {u - door_u:+.2f} m from its door")\n    return out\n\n\ndef _say(findings, msg):\n    if findings is not None:\n        findings.append(msg)\n', 'tests/test_site_night_drop.py': '"""A bank\'s night depository beside its door (`site_night_drop`, Zoo 1.138.0\'s `night_drop`): on the facade its sign is\nover, clear of the openings, facing out, hung. FAILS ON 0.131.0, which hangs none.\n"""\nimport math\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\n\nimport site_night_drop as N   # noqa: E402\nimport site_posters as SP     # noqa: E402\n\nRECT = (60.0, 12.0, 80.0, 30.0)       # a bank 20 x 18, its south face on y 12\nBDEF = {"id": "bank", "at": [70.0, 21.0], "rot": 0}\n\n\ndef _merged(openings):\n    # storey-0 exterior openings on the south wall, in the building\'s frame (its centre at (70, 21))\n    return {"openings": [{"building": "bank", "wall": "ext_0_S", "story": 0, "x": x - 70.0, "y": -9.0, "width": w,\n                          "kind": k} for x, w, k in openings]}\n\n\ndef _plan(openings, rect=RECT):\n    findings = []\n    got = N.plan({"buildings": [BDEF]}, _merged(openings), [("bank", (70.0, 11.6), "bank_branch_a02")],\n                 {"bank": rect}, findings)\n    return got, findings\n\n\ndef test_it_hangs_beside_the_door_clear_of_it_facing_the_street():\n    (r,), _f = _plan([(70.0, 1.8, "door")])\n    assert r["species"] == "night_drop" and r["z"] == N.CENTRE_Z and tuple(r["dims"]) == N.DIMS\n    # beside the door, OPENING_KEEP clear of it\n    u = r["at"][0]\n    assert abs(u - 70.0) == pytest.approx(0.9 + SP.OPENING_KEEP + N.DIMS[0] / 2.0)\n    # off the south face by half its depth and the air, facing south (-y)\n    assert r["at"][1] == pytest.approx(12.0 - N.DIMS[1] / 2.0 - SP.AIR)\n    y = math.radians(r["yaw"])\n    assert (math.sin(y), -math.cos(y)) == pytest.approx((0.0, -1.0), abs=1e-9)\n\n\ndef test_a_window_beside_the_door_moves_it_to_the_other_side_or_the_nearest_span():\n    # windows tight on the door\'s +x side: it goes to the -x side\n    (r,), _f = _plan([(70.0, 1.8, "door"), (72.4, 2.0, "window")])\n    assert r["at"][0] < 70.0\n    # windows tight on both: the nearest free span, its end nearest the door\n    (r,), _f = _plan([(70.0, 1.8, "door"), (72.4, 2.0, "window"), (67.6, 2.0, "window")])\n    lo_hole = 67.6 - 1.0 - SP.OPENING_KEEP\n    hi_hole = 72.4 + 1.0 + SP.OPENING_KEEP\n    u = r["at"][0]\n    assert u - N.DIMS[0] / 2.0 >= hi_hole - 1e-9 or u + N.DIMS[0] / 2.0 <= lo_hole + 1e-9\n    assert min(abs(u - N.DIMS[0] / 2.0 - hi_hole), abs(u + N.DIMS[0] / 2.0 - lo_hole)) < 1e-6\n\n\ndef test_a_facade_with_no_room_or_no_door_hangs_none_and_says_so():\n    # a 4 m facade, a 2.6 m door: no 0.6 m clear of it and the corners\n    got, findings = _plan([(70.0, 2.6, "door")], rect=(68.0, 12.0, 72.0, 30.0))\n    assert got == [] and any("LOT_NIGHT_DROP_NO_ROOM" in f for f in findings), findings\n    got, findings = _plan([])\n    assert got == [] and any("LOT_NIGHT_DROP_NO_DOOR" in f for f in findings), findings\n'}
CHANGELOG = '## 0.133.0 - a bank\'s night depository beside its door\n\n**The walker\'s bank list, outside** (the factory\'s `docs/reference/BANK_INTERIOR_COMPS.md`, researched): "a night\ndepository is a slot in the wall for after-hours deposits". Zoo 1.138.0 draws it (`night_drop`); this hangs it, the last\nof the list\'s three outside pieces.\n\n### Added\n- **`site_night_drop`: a bank\'s night depository on its storefront.**\n  - It goes on the facade its door sign is over (`lot.bank_fronts`), beside the door nearest the sign.\n    `site_posters.OPENING_KEEP` keeps it clear of that door and of every other storey-0 opening (a storefront\'s\n    windows), and `site_posters.CORNER_KEEP` from the corners.\n  - The door\'s two sides are tried first, then the free span nearest the door that holds the 0.6 m plate.\n  - **Hung, as a poster run is** (`site_posters`): its own list, never cover, a slot all the same, no collision. Its\n    back sits `site_posters.AIR` off the wall\'s face, its front turned out (`facing_yaw`), its centre 1.1 m up so the\n    chute is about a metre off the ground.\n  - Refused and said, never forced: `LOT_NIGHT_DROP_NO_DOOR`, `LOT_NIGHT_DROP_NO_ROOM`.\n  - Why not Zoo\'s fixture pass, which stands the door sign: that is the light-anchor pipeline, its rows choosing what\n    Lux lights, and a night drop is not a light.\n\n### Measured, the bank level (bank_block_001, seed 9082) assembled by this\n- `LOT_NIGHT_DROP: b0 on its S facade at +1.60 m from its door`: at (-61.40, -18.05), yaw 0 (facing the street),\n  1.1 m up.\n- The drive-up and the bank\'s sign are where 0.132.0 put them.\n\n### Tests\n- `tests/test_site_night_drop.py` (new; fails on 0.132.0):\n  - it hangs beside the door, clear of it, facing the street;\n  - a window beside the door moves it to the other side, or to the nearest free span;\n  - a facade with no room, or no door, hangs none and says so.\n\n'
OLD_VERSION, NEW_VERSION = 'Lot 0.132.0', 'Lot 0.133.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: lot/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: lot/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: lot/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: lot/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## " + OLD_VERSION.split()[-1].encode() + b" "):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in lot/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
